<aside class="site-sidebar" aria-label="侧边栏">
    <?php $load = static fn() => get_users(['role__in' => ['administrator', 'editor'], 'number' => 1, 'orderby' => 'ID']); $authors = get_theme_mod('sidebar_profile', true) ? (function_exists('timellow_cached_data') ? timellow_cached_data('profile_author', $load) : $load()) : []; $author = $authors ? $authors[0] : null; $name = $author ? $author->display_name : get_bloginfo('name'); $avatar = get_theme_mod('sidebar_profile_avatar') ?: ($author ? get_avatar_url($author, ['size' => 144, 'force_display' => true]) : ''); $bio = get_theme_mod('sidebar_profile_bio') ?: timellow_subtitle(); ?>
    <?php if (get_theme_mod('sidebar_profile', true)): ?><section class="sidebar-widget sidebar-profile-widget"><div class="sidebar-profile">
        <div class="sidebar-profile-avatar" aria-hidden="true"><?php if ($avatar): ?><img src="<?php echo esc_url($avatar); ?>" alt="" loading="eager" decoding="async"><?php else: ?><span><?php echo esc_html(timellow_first_character($name)); ?></span><?php endif; ?></div>
        <h2 class="sidebar-profile-name"><?php echo esc_html($name); ?></h2><p class="sidebar-profile-bio"><?php echo esc_html($bio); ?></p>
    </div><?php timellow_render_social('sidebar-profile-links'); ?></section><?php endif; ?>
    <?php $load = static fn() => get_posts(['numberposts' => 5]); $recent = get_theme_mod('sidebar_latest_posts', true) ? (function_exists('timellow_cached_data') ? timellow_cached_data('recent_posts', $load) : $load()) : []; if ($recent): ?><section class="sidebar-widget"><h2 class="sidebar-widget-title">最新文章</h2><ol class="sidebar-list"><?php foreach ($recent as $post): ?><li class="sidebar-list-item"><a class="sidebar-item-link" href="<?php echo esc_url(get_permalink($post)); ?>"><span class="sidebar-item-title"><?php echo esc_html(get_the_title($post)); ?></span><span class="sidebar-item-meta"><?php echo esc_html(get_the_date('Y-m-d', $post)); ?></span></a></li><?php endforeach; ?></ol></section><?php endif; ?>
    <?php $load = static fn() => get_posts(['numberposts' => 5, 'orderby' => 'comment_count']); $popular = get_theme_mod('sidebar_popular_posts', true) ? (function_exists('timellow_cached_data') ? timellow_cached_data('popular_posts', $load) : $load()) : []; if ($popular): ?><section class="sidebar-widget"><h2 class="sidebar-widget-title">热门文章</h2><ol class="sidebar-list"><?php foreach ($popular as $post): ?><li class="sidebar-list-item"><a class="sidebar-item-link" href="<?php echo esc_url(get_permalink($post)); ?>"><span class="sidebar-item-title"><?php echo esc_html(get_the_title($post)); ?></span><span class="sidebar-item-meta"><?php echo (int) $post->comment_count; ?> 条评论</span></a></li><?php endforeach; ?></ol></section><?php endif; ?>
    <?php $load = static fn() => get_comments(['number' => 5, 'status' => 'approve']); $comments = get_theme_mod('sidebar_latest_comments', true) ? (function_exists('timellow_cached_data') ? timellow_cached_data('recent_comments', $load) : $load()) : []; if ($comments): ?><section class="sidebar-widget"><h2 class="sidebar-widget-title">最新评论</h2><ol class="sidebar-list sidebar-comment-list"><?php foreach ($comments as $comment): ?><li class="sidebar-list-item"><a class="sidebar-item-link" href="<?php echo esc_url(get_comment_link($comment)); ?>"><span class="sidebar-comment-author"><?php echo esc_html($comment->comment_author); ?></span><span class="sidebar-comment-text"><?php echo esc_html(wp_trim_words($comment->comment_content, 16)); ?></span><span class="sidebar-item-meta"><?php echo esc_html(get_comment_date('Y-m-d', $comment)); ?></span></a></li><?php endforeach; ?></ol></section><?php endif; ?>
    <?php $load = static fn() => get_posts(['post_type' => 'timellow_moment', 'numberposts' => 3]); $moments = get_theme_mod('sidebar_latest_moments', true) ? (function_exists('timellow_cached_data') ? timellow_cached_data('recent_moments', $load) : $load()) : []; $moments_page = $moments ? timellow_moments_page() : null; if ($moments): ?><section class="sidebar-widget"><h2 class="sidebar-widget-title">最新说说</h2><ol class="sidebar-list sidebar-moment-list"><?php foreach ($moments as $moment): ?><li class="sidebar-list-item"><a class="sidebar-item-link" href="<?php echo esc_url($moments_page ? get_permalink($moments_page) . '#moment-' . $moment->ID : get_permalink($moment)); ?>"><span class="sidebar-moment-text"><?php echo esc_html(wp_trim_words(wp_strip_all_tags(get_the_excerpt($moment) ?: $moment->post_content), 18)); ?></span><span class="sidebar-item-meta"><?php echo esc_html(get_the_date('Y-m-d', $moment)); ?></span></a></li><?php endforeach; ?></ol></section><?php endif; ?>
    <?php if (is_active_sidebar('timellow-sidebar')) dynamic_sidebar('timellow-sidebar'); ?>
</aside>
